# Apply the compatibility transformations that Kubebuilder's generic Helm
# plugin cannot infer. Everything under chart/templates that the plugin owns is
# regenerated by `make manifests`, so a hand edit there does not survive. This
# script is where such an edit belongs.
#
# Two transformations:
#
#   1. The legacy chart exposes imagePullSecrets at the top level. Keep the
#      generated manager template otherwise identical to CAPLL.
#   2. Every namespaced resource, and every namespace reference inside a
#      cluster-scoped one, resolves through the namespaceName template rather
#      than reading .Release.Namespace directly, so namespaceOverride reaches
#      all of them.
#
# Each transformation fails the build when its expected input is absent, rather
# than silently producing a chart that is missing it.

set -euo pipefail

CHART_TEMPLATES="${CHART_TEMPLATES:-chart/templates}"
manager_template="${1:-${CHART_TEMPLATES}/manager/manager.yaml}"

# ---------------------------------------------------------------------------
# 1. imagePullSecrets
# ---------------------------------------------------------------------------
temporary="${manager_template}.tmp"
trap 'rm -f "${temporary}"' EXIT

old='{{- with .Values.manager.imagePullSecrets }}'
new='{{- with (coalesce .Values.manager.imagePullSecrets .Values.imagePullSecrets) }}'

sed "s|${old}|${new}|" "${manager_template}" > "${temporary}"
if cmp -s "${manager_template}" "${temporary}"; then
  echo "Helm manager imagePullSecrets hook was not found in ${manager_template}" >&2
  exit 1
fi
mv "${temporary}" "${manager_template}"

# ---------------------------------------------------------------------------
# 2. namespaceName
# ---------------------------------------------------------------------------
# These four are not regenerated by the Helm plugin, and each reads
# .Release.Namespace deliberately:
#
#   _helpers.tpl    defines namespaceName, so it is the one place that may
#                   read .Release.Namespace
#   namespace.yaml  names the Namespace through namespaceName already
#   validate.yaml   compares namespaceOverride against the release namespace,
#                   which is the comparison it exists to make
#   NOTES.txt       prints `helm status -n <release namespace>`, and Helm
#                   stores the release in the release namespace whatever the
#                   override says
namespace_old='{{ .Release.Namespace }}'
namespace_new='{{ include "cluster-api-provider-nico.namespaceName" . }}'
namespace_rewritten=0

while IFS= read -r template; do
  case "$(basename "${template}")" in
    _helpers.tpl|namespace.yaml|validate.yaml|NOTES.txt) continue ;;
  esac
  grep -qF "${namespace_old}" "${template}" || continue
  temporary="${template}.tmp"
  sed "s|${namespace_old}|${namespace_new}|g" "${template}" > "${temporary}"
  mv "${temporary}" "${template}"
  namespace_rewritten=$((namespace_rewritten + 1))
done < <(find "${CHART_TEMPLATES}" -type f \( -name '*.yaml' -o -name '*.tpl' \) | sort)

if (( namespace_rewritten == 0 )); then
  echo "No .Release.Namespace references were found under ${CHART_TEMPLATES}." >&2
  echo "The Helm plugin's output changed; check whether this fixup is still needed." >&2
  exit 1
fi

echo "helm-chart-fixups: rewrote the namespace reference in ${namespace_rewritten} templates"
